import React from 'react';

const ChampionsLeagueHeader = () => {
  return (
    <header className="bg-champions-blue p-4 flex justify-between items-center shadow-md">
      {/* Logo y título principal */}
      <div className="flex items-center">
        <div className="champions-logo"></div>
        <div className="ml-4">
          <h2 className="text-white font-bold text-xl">UEFA Champions League</h2>
          <p className="text-blue-300 text-sm">Estadísticas Históricas</p>
        </div>
      </div>

      {/* Navegación */}
      <nav className="hidden md:flex space-x-6">
        <a href="#" className="text-white hover:text-champions-gold transition-colors">
          Inicio
        </a>
        <a href="#" className="text-white hover:text-champions-gold transition-colors">
          Equipos
        </a>
        <a href="#" className="text-white hover:text-champions-gold transition-colors">
          Jugadores
        </a>
        <a href="#" className="text-white hover:text-champions-gold transition-colors">
          Temporadas
        </a>
      </nav>

      {/* Decoración de estrellas */}
      <div className="hidden md:flex items-center space-x-1">
        {[1, 2, 3].map((star) => (
          <span key={star} className="champions-star" style={{ animationDelay: `${star * 0.3}s` }}>★</span>
        ))}
      </div>
    </header>
  );
};

export default ChampionsLeagueHeader;
